def esc(x): return html.escape(str(x))

def img_cards(folder, captions):
    out=[]
    for name, caption in captions:
        if (root/folder/name).exists():
            src=(Path(folder)/name).as_posix()
            out.append(f'''<figure class="shot" onclick="openImg(this)"><img src="{src}" alt="{esc(caption)}"><figcaption><b>{esc(name)}</b><span>{esc(caption)}</span></figcaption></figure>''')
    return '\n'.join(out)

