def shell(title,body,active=''):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Vitalis Gitonga Data Analytics portfolio"><title>{esc(title)}</title><style>{common_css}</style></head><body><nav><div class="wrap nav"><a class="logo" href="index.html">VITALIS<i>.</i></a><div class="links"><a href="index.html">Home</a><a href="swiftlog.html">SwiftLog</a><a href="fintrust.html">FinTrust</a><a href="index.html#contact">Contact</a></div></div></nav>{body}<footer><div class="wrap">© 2026 Vitalis Gitonga · Data Analytics & Business Intelligence · <a href="mailto:ndunguvitalis@gmail.com">ndunguvitalis@gmail.com</a> · <a href="https://www.linkedin.com/in/vitalis-gitonga-615aba201/?isSelfProfile=true" target="_blank">LinkedIn</a></div></footer><div class="lightbox" id="lb" onclick="closeImg()"><button class="close" onclick="closeImg()">×</button><img id="lbimg" alt=""></div><script>function openImg(el){{event.stopPropagation();document.getElementById('lbimg').src=el.querySelector('img').src;document.getElementById('lbimg').alt=el.querySelector('figcaption span').textContent;document.getElementById('lb').classList.add('open')}}function closeImg(){{document.getElementById('lb').classList.remove('open')}}document.addEventListener('keydown',e=>{{if(e.key==='Escape')closeImg()}});</script></body></html>'''

